<?php
require __DIR__.'/config.php';require_role(['admin','teacher']);$students=read_json('students');$results=read_json('results');$attendance=read_json('attendance');
$rows=[];foreach($students as $s){$sid=(int)$s['id'];$rs=array_values(array_filter($results,fn($r)=>(int)($r['student_id']??0)===$sid));$at=array_values(array_filter($attendance,fn($r)=>(int)($r['student_id']??0)===$sid));$avg=count($rs)?round(array_sum(array_map(fn($r)=>((float)$r['mark']/max(1,(float)$r['out_of']??100))*100,$rs))/count($rs),1):0;$present=count(array_filter($at,fn($x)=>($x['status']??'')==='Present'));$pct=count($at)?round($present/count($at)*100,1):0;$rows[]=['name'=>$s['name']??'Student','grade'=>$s['grade']??'','average'=>$avg,'attendance'=>$pct];}
if(($_GET['format']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="ridgefield_student_report.csv"');$out=fopen('php://output','w');fputcsv($out,['Student','Grade','Average %','Attendance %']);foreach($rows as $r)fputcsv($out,$r);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1100px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #ddd;border-radius:14px;padding:18px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.btn{padding:9px 12px;background:#17231f;color:#fff;text-decoration:none;border-radius:8px}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="control-centre.php">← Control Centre</a></p><h1>Student Performance Report</h1><p><a class="btn" href="?format=csv">Export CSV</a></p><div class="card"><table><tr><th>Student</th><th>Grade</th><th>Average</th><th>Attendance</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['grade'])?></td><td><?=h($r['average'])?>%</td><td><?=h($r['attendance'])?>%</td></tr><?php endforeach;?></table></div></div><script src="assets/dynamic-site.js"></script>
</body></html>